// Shared navigation, contextual help and first-visit guide. No quantum model
// or audio-effect mapping is added here. Preferences never overwrite sessions.
const $=id=>document.getElementById(id),SEEN='pundora-guide-seen-v1',BENCHES=['music','studio','guide'];
let active='music',tourAt=0,tourReturn='music',tourFocus=null,tipOwner=null,tipTimer=null,hideTimer=null;
function activate(name,{focus=false}={}){
  if(!BENCHES.includes(name))return;window.quantumLab?.stop();window.quantumStudio?.stop();active=name;document.dispatchEvent(new window.CustomEvent('lab:activated',{detail:name}));
  for(const n of BENCHES){const selected=n===name;$('tab-'+n).classList.toggle('active',selected);$('tab-'+n).setAttribute('aria-selected',String(selected));$('tab-'+n).tabIndex=selected?0:-1;$(n==='guide'?'guide-workbench':n+'-workbench').hidden=!selected;}
  if(name==='studio')window.quantumStudio?.compute();if(focus)$('tab-'+name).focus();hideTip();
}
for(const name of BENCHES)$('tab-'+name).addEventListener('click',()=>activate(name));
document.querySelector('.bench-tabs').addEventListener('keydown',e=>{const at=BENCHES.indexOf(active);let next;if(e.key==='ArrowRight')next=(at+1)%3;else if(e.key==='ArrowLeft')next=(at+2)%3;else if(e.key==='Home')next=0;else if(e.key==='End')next=2;else return;e.preventDefault();activate(BENCHES[next],{focus:true});});
document.querySelector('a[href="#physics"]')?.addEventListener('click',()=>activate('music'));
function wrapAdvanced(panel,label,{open=false}={}){
  if(!panel)return null;const box=document.createElement('details');box.className='advanced-block'+(panel.classList.contains('studio-wide')?' studio-wide':'');box.open=open;
  const summary=document.createElement('summary');summary.textContent=label;box.append(summary);panel.before(box);box.append(panel);return box;
}
function jump(id){const el=$(id);if(!el)return;for(let p=el.parentElement;p;p=p.parentElement)if(p.tagName==='DETAILS')p.open=true;if(el.tagName==='DETAILS')el.open=true;el.scrollIntoView({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}
// Music: keep state and probabilities adjacent; reveal sound design on demand.
const musicSound=wrapAdvanced(document.querySelector('.sound-panel'),'Sound design · oscillator, filter & note length');musicSound?.classList.add('music-wide');
document.querySelector('.tuning-panel').classList.add('music-wide');
const mapTable=document.querySelector('.tuning-panel .table-scroll'),mapDetails=wrapAdvanced(mapTable,'Edit the four outcome notes');
if(mapDetails){mapDetails.classList.add('mapping-details');const chips=document.querySelector('.tuning-chips');mapDetails.append(chips);}
const musicTransport=document.querySelector('#music-workbench .transport'),musicExports=$('music-exports');musicTransport.after(musicExports);
const musicJump=document.createElement('button');musicJump.className='secondary-button';musicJump.textContent='Export';musicJump.id='music-export-jump';musicJump.addEventListener('click',()=>jump('music-exports'));musicTransport.querySelector('.transport-main').append(musicJump);
const compareNote=document.createElement('p');compareNote.id='music-compare-help';compareNote.className='micro-note';compareNote.textContent='For A/B, choose Just intonation or Custom tuning. A uses 12-TET; B uses the selected tuning.';$('compare').after(compareNote);
// NMR: exports remain inside its own workspace and retain their existing hooks.
const nmrExports=document.createElement('details');nmrExports.id='studio-exports';nmrExports.className='export-panel';
nmrExports.innerHTML='<summary>Export from NMR Lab <span>Audio · Data · Diagrams · Session</span></summary><div class="export-grid"><section id="ui-nmr-audio"><h3>Audio</h3><p>Current NMR sonification, duration, routing and level.</p></section><section id="ui-nmr-data"><h3>Data</h3><p>Complex quadratures, FID/Unity JSON and reference-note table.</p></section><section id="ui-nmr-diagrams"><h3>Diagrams</h3><p>FID, decay envelopes and Fourier spectrum, with labels.</p></section><section id="ui-nmr-session"><h3>Session</h3><p>NMR JSON includes its configuration and any imported effective matrix.</p></section></div><p class="export-status">Downloads stay in this browser’s download location. These exports use the NMR Lab settings, independently of Music Lab.</p>';
const nmrTransport=document.querySelector('.studio-transport');nmrTransport.after(nmrExports);
for(const id of ['s-wav','s-mp3','s-cancel'])$('ui-nmr-audio').append($(id));
for(const id of ['s-fid-json','s-fid-csv','s-note-csv'])$('ui-nmr-data').append($(id));
for(const id of ['s-export','s-import','s-save','s-restore'])$('ui-nmr-session').append($(id));
const fidDownloads=document.querySelector('.fid-download');$('ui-nmr-diagrams').append(fidDownloads);
const formats=document.createElement('details');formats.innerHTML='<summary>More diagram formats</summary>';formats.className='diagram-formats';
document.querySelectorAll('.plot-actions').forEach(el=>{el.querySelectorAll('button').forEach(b=>{b.textContent=({fid:'FID',decay:'Decay',spectrum:'Spectrum'}[b.dataset.image])+' '+b.dataset.ext.toUpperCase();});formats.append(el);});$('ui-nmr-diagrams').append(formats);
const nmrJump=document.createElement('button');nmrJump.className='secondary-button';nmrJump.textContent='Export';nmrJump.id='studio-export-jump';nmrJump.addEventListener('click',()=>jump('studio-exports'));nmrTransport.querySelector('#s-stop').after(nmrJump);
const sections=[...document.querySelectorAll('.studio-layout>section')],find=title=>sections.find(x=>x.querySelector('h2')?.textContent===title);
const circuit=find('Build the quantum circuit'),rho=find('Import an effective density matrix');
const circuitBox=wrapAdvanced(circuit,'Circuit editor · active preparation'),rhoBox=wrapAdvanced(rho,'State from a density matrix');
if(circuitBox)circuitBox.id='ui-circuit-details';if(rhoBox)rhoBox.id='ui-rho-details';
wrapAdvanced(find('T₂ vs T₂* & spin echo'),'Explore T₂, T₂* & ideal spin echo');
wrapAdvanced(find('Fourier spectrum'),'Explore the Fourier spectrum');
wrapAdvanced(find('NMR measurement, annotated with sound'),'Methods, assumptions & session tools');
const layout=document.querySelector('.studio-layout'),prepare=find('Prepare & relax each qubit'),fid=find('Acquire the FID'),model=find('Choose your model & molecule');
// The active circuit stays clearly summarized even when its editor is closed.
model.after(prepare);prepare.after(fid);fid.after(circuitBox);circuitBox.after(rhoBox);
const moleculeCards=model.querySelector('.molecules');wrapAdvanced(moleculeCards,'Molecule presets · illustrative values');
const sourceNote=document.createElement('p');sourceNote.id='ui-active-preparation';sourceNote.className='active-preparation';circuitBox.before(sourceNote);
function summarize(c){
  const gates=c.circuit.map(g=>g.type+(g.type==='Wait'?` ${g.ms} ms`:' q'+g.q));
  const initial=c.densityInput?'Imported effective matrix ('+c.densityInput.treatment+')':'Bloch product preparation';
  sourceNote.textContent=`Active NMR preparation: ${initial}; ${gates.length?gates.join(' → '):'no circuit gates'}; readout ${c.readout}; echo ${c.echo?'on':'off'}.`;
  circuitBox.querySelector('summary').textContent=`Circuit editor · ${c.circuit.length} active gate${c.circuit.length===1?'':'s'}`;
  rhoBox.querySelector('summary').textContent=c.densityInput?'State from a density matrix · active':'State from a density matrix';
}
document.addEventListener('studio:configuration',e=>summarize(e.detail));summarize(window.quantumStudio.getConfiguration());
// Direct audio formats stay visible next to playback, even with Export closed.
for(const [bench,ids] of [['music',['music-wav','music-mp3']],['studio',['s-wav','s-mp3']]]){
 const row=document.createElement('div');row.className='quick-downloads';row.id=bench+'-quick-downloads';row.setAttribute('aria-label',bench==='music'?'Music audio downloads':'NMR audio downloads');
 for(const id of ids){const original=$(id),b=document.createElement('button');b.id=id+'-quick';b.className='secondary-button';b.textContent=id.includes('wav')?'WAV ↓':'MP3 ↓';b.dataset.help='Export audio from this lab using its current export settings. More options are in Export.';b.addEventListener('click',()=>{original.click();});new window.MutationObserver(()=>b.disabled=original.disabled).observe(original,{attributes:true,attributeFilter:['disabled']});row.append(b);}
 if(bench==='music')musicTransport.append(row);else nmrTransport.insertBefore(row,$('s-progress'));
}
// Guide is a dedicated, persistent tab; there is no extra floating help card.
$('guide-workbench').innerHTML=`
<section class="guide-intro"><p class="eyebrow">YOUR LAB COMPANION</p><h2>A state. A mapping. A sound you can explain.</h2><p>Music Lab translates two-qubit probabilities into notes. NMR Lab translates a simulated spin signal into audio. Both use a classical synthesizer and keep their own settings.</p><button id="guide-replay" class="play-button">Replay the first-visit tour</button></section>
<nav class="guide-index" aria-label="Guide contents"><a href="#guide-first">First sound</a><a href="#guide-phenomena">Experiments</a><a href="#guide-exports">Exports</a><a href="#guide-science">Meaning & limits</a></nav>
<section class="guide-card" id="guide-first"><h2>Your first sound</h2><ol><li>Open Music Lab. Start with the two independent qubits; CNOT is off.</li><li>Move a polar angle θ and watch the exact probability bars. The spheres show reduced states after the preparation circuit.</li><li>Press Play. Measured melody assigns one sampled outcome to one note in each step. Probability chord translates all four probabilities into voice levels.</li><li>Choose a root note and edit the four outcome notes. Two outcomes mapped to the same frequency can sound identical even when their probabilities change.</li><li>Open Export in this same tab. Select 1–16 loops, Clean/Processed/Both and a tail policy, then download WAV/MP3, data, a chart or the session JSON.</li></ol><p>Audio begins after your click. The same 16-step take repeats until you select New take or change its probabilities. Each simulated shot assumes a fresh preparation.</p><button data-guide-bench="music" class="secondary-button">Open Music Lab</button></section>
<section class="guide-card" id="guide-phenomena"><h2>Choose an experiment</h2><p>Loading an example replaces Music Lab settings. Export your current session first if you want to keep it.</p><div class="lesson-grid">
<article><h3>Probabilities → melody</h3><p><b>Change:</b> θ with CNOT off and Z readout. <b>Observe:</b> populations and note occurrence rates. <b>Hear:</b> different distributions across the four assigned notes.</p><button data-lesson="basic" class="secondary-button">Load simple preparation</button></article>
<article><h3>Relative phase</h3><p><b>Change:</b> q0 phase φ in the X basis. <b>Observe:</b> probabilities shift between 00 and 10; Z populations stay unchanged. <b>Hear:</b> the shift only when those outcomes have distinguishable note mappings.</p><button data-lesson="phase" class="secondary-button">Load phase example</button></article>
<article><h3>Bell correlations</h3><p><b>Change:</b> Z⊗Z, X⊗X and X⊗Z measurement bases. <b>Observe:</b> joint correlations and zero local Bloch vectors for ideal Bell. A note sequence alone cannot certify entanglement.</p><button data-lesson="bell" class="secondary-button">Load Bell example</button></article>
<article><h3>Compare tunings</h3><p><b>Change:</b> Just intonation or custom cents. <b>Observe:</b> mapped frequencies and cents. <b>Hear:</b> A/B repeats the same take in 12-TET and the selected tuning. This changes the musical mapping.</p><button data-lesson="tuning" class="secondary-button">Load tuning example</button></article>
<article><h3>Relaxation & FID</h3><p><b>Change:</b> T₁, T₂ and T₂* in NMR Lab. <b>Observe:</b> populations, transverse coherence, time signal and spectrum. <b>Hear:</b> their effect through the selected sonification. Values remain simulation assumptions.</p><button data-guide-bench="studio" class="secondary-button">Open NMR Lab</button></article>
<article><h3>Ideal spin echo</h3><p>Open the T₂/T₂* section. The Hahn example refocuses static frequency spread while irreversible T₂ loss remains. NMR spin echo is a spin-control sequence; an audio delay repeats an already generated sound.</p><button data-guide-section="echo" class="secondary-button">Find the echo lesson</button></article></div></section>
<section class="guide-card"><h2>Build a circuit and shape its sound</h2><ol><li>In Music Lab choose New |00⟩ circuit, or load a known X, H, H→H, H→Z→H or Bell example. Examples replace the preparation and note mapping.</li><li>Select a gate and wire, set an angle for Rx/Ry/Rz, then Add gate. CNOT uses that wire as control. Select a placed gate to move, remove or edit its rotation angle. Undo edit restores the last saved edit.</li><li>Read the selected gate’s before/after probabilities. Audition before and after plays one clean 16-step take from the selected intermediate state, using the same seed. The main Bloch spheres still show the complete circuit.</li><li>Choose distinct outcome notes. A phase gate alone can leave Z probabilities unchanged; later mixing gates or X/Y readout may expose its phase.</li><li>Choose Clean sine preset for a simple oscillator with FX off. Enable Drive, Delay/Echo or Reverb individually, adjust wet/dry and move effects Earlier/Later to change their order. Editing stops a preview.</li><li>Listen Clean / Processed compares one frozen take with the rack bypassed and enabled. The same level is used; there is no automatic loudness matching.</li><li>Export Clean, Processed or Both. Both downloads two files. Choose an FX tail up to 12 seconds or an explicit 0.30-second trim. Trimmed/capped endings have a short fade. Session JSON retains all circuit and FX settings.</li></ol><p>In NMR Lab, choose Model-linked BPM and leave Audible pulse on. A selected q0/q1 T₂ or T₂* maps to 120–180 BPM: shorter time gives a faster pulse. Open Rhythm mapping & comparison to choose the source, reference and pulse depth. At the reference time the tempo is 150 BPM. Use Fixed BPM or Listen A/B · Fixed / model for comparison, and Without pulse to hear the underlying sonification. Audio seconds stay independent of BPM, so the same FID window is stretched by the same amount. Physical T₁/T₂ and raw FID quadratures are not altered by this rhythmic gain. Fit duration to beats is available only in Fixed mode with the pulse off; it changes time stretching.</p></section>
<section class="guide-card" id="guide-exports"><h2>What can I export?</h2><div class="guide-table"><table><thead><tr><th>Object</th><th>Music Lab</th><th>NMR Lab</th></tr></thead><tbody><tr><td>Audio</td><td>WAV / MP3 of the current take, 1–16 loops, oscillator/filter/level and the selected release/FX tail policy (maximum 12 s).</td><td>WAV / MP3 of the selected FID, transition or population sonification and duration.</td></tr><tr><td>Data</td><td>CSV of exact probabilities, frequencies and current take counts.</td><td>Complex FID CSV, FID/Unity JSON and the 36-note reference CSV.</td></tr><tr><td>Diagram</td><td>Labelled probability PNG.</td><td>FID, envelope and Fourier-spectrum PNG/JPG/JPEG.</td></tr><tr><td>Session</td><td>JSON with preparation, bases, musical settings, probabilities, seed, take and export-loop count.</td><td>Separate NMR JSON with its configuration and any imported effective matrix/treatment.</td></tr></tbody></table></div><p>Export inside the same tab in which you work. Files go to the browser’s download location; this app does not collect them in a separate library tab. Browser saves remain on that browser/device. Session JSON is the portable backup. The two session formats are independent. Direct WAV and MP3 buttons are also next to playback. Music JSON includes the complete added circuit, FX order and parameters. NMR WAV/MP3 uses the selected fixed/model tempo and pulse envelope. Session JSON records the mapping, source qubit, reference, pulse depth and derived BPM. FID CSV remains the physical quadratures. Model-linked mode keeps seconds independent of BPM. Fit duration to beats is available with Fixed / pulse off.</p><p>Music WAV uses 44.1 kHz stereo PCM16, MP3 128 kbps. The live oscillator/envelope/filter/level/compressor graph is reused for offline rendering. The scheduling lead is trimmed. Choose Clean, Processed or Both, and include the FX tail (up to 12 s) or trim to 0.30 s. No output peak/RMS normalization is added; the synthetic reverb impulse itself has fixed unit energy. MP3 encoding can add padding. Export freezes the current settings and take.</p></section>
<section class="guide-card" id="guide-science"><h2>What changes the sound?</h2><p><b>Quantum model:</b> preparation gates and measurement bases determine the simulated state and outcome probabilities. A gate does not have a universal sound of its own. Different states can sound the same under a chosen basis or note mapping.</p><p><b>Musical mapping:</b> outcome notes, tuning, rhythm, oscillator and filtering determine the classical audio. A4=435 Hz anchors the reference bank. Relative quantum phases are not directly oscillator phases in the probability-based Music Lab.</p><p><b>NMR model:</b> effective states, physical pseudo-pure ensembles, readout and local FID have distinct meanings. A Bell effective state has no local FID with the specified local observation; this does not mean all joint coherence is absent. Imported invalid effective matrices need explicit treatment before use.</p><p>Music Lab now includes an ordered two-wire gate editor and a classical Drive, Delay/Echo and Reverb rack. Select a gate for before/after probabilities and clean auditions. FX can be bypassed or reordered. A controlled Clean/Processed comparison reuses the same take. Existing NMR logical gates and creative texture retain their separate scope.</p></section>
<section class="guide-card"><h2>Finding help & recovering your work</h2><p>Hover over unfamiliar controls or focus them with Tab. Short explanations also have small info buttons at key controls for touch. Escape dismisses a tooltip. The guide tab always remains available.</p><p>For a new NMR example, check the visible active-preparation summary: closing an advanced section does not disable its settings. Reset and demo buttons change preparation; Undo can restore the previous NMR configuration. Session import restores that bench’s settings.</p><p>The first-visit tour is remembered in this browser where local storage is available. Private browsing, cleared site data or another browser can show it again. The tour itself never loads a preset or starts audio.</p></section>`;
document.querySelectorAll('[data-guide-bench]').forEach(b=>b.addEventListener('click',()=>{activate(b.dataset.guideBench);$('tab-'+b.dataset.guideBench).scrollIntoView({block:'start'});}));
document.querySelectorAll('[data-lesson]').forEach(b=>b.addEventListener('click',()=>{
  const session=window.quantumLab.getSession(),cfg=session.config,kind=b.dataset.lesson;
  Object.assign(cfg,{theta0:Math.PI/2,theta1:Math.PI/2,phi0:0,phi1:0,cnot:false,circuit:[],basis0:'Z',basis1:'Z',tuning:kind==='tuning'?'just':'equal',mode:'shots',degrees:[0,4,7,12],wave:'triangle',cutoff:3200,volume:-12});
  if(kind==='phase')Object.assign(cfg,{theta1:0,basis0:'X'});if(kind==='bell')Object.assign(cfg,{theta1:0,cnot:true});
  window.quantumLab.restore(JSON.stringify(session));activate('music');jump('music-workbench');
}));
document.querySelector('[data-guide-section="echo"]').addEventListener('click',()=>{activate('studio');const target=layout.querySelector('details summary');const echo=find('T₂ vs T₂* & spin echo');if(echo)jump(echo.id||(echo.id='ui-echo-panel'));});
// Accessible short explanations: hover/focus, hoverable content, Escape and tap.
const help={
 's-bpm':'Model-linked mode displays the derived tempo, 120–180 BPM. Fixed mode lets you enter a comparison tempo. Audible pulse must be on to hear rhythmic gain.',
 's-tempo-sync':'Available only in Fixed mode with pulse off. Fits duration to beats × 60/BPM; changing this also changes physical-to-audio time stretching.',
 's-tempo-mode':'Model-linked converts the selected relaxation time into a bounded artistic rhythm. Fixed keeps a chosen tempo for comparison.',
 's-rhythm':'Apply a smooth repeated gain pulse to both audible channels. Bypass leaves the physical FID unchanged.',
 's-tempo-reference':'Selected T = this reference gives 150 BPM. The reference stays fixed when changing times or qubits.',
 's-tempo-source':'Choose homogeneous T₂ or the modeled FID 1/e time T₂*. These are decay times, not physical beat periods.',
 's-tempo-qubit':'Only this qubit supplies the time for the shared musical pulse; observation routing is a separate choice.',
 's-rhythm-depth':'0% is identical to bypass; 100% reaches silence between smooth pulses.',
 's-fixed-bpm':'The fixed 120–180 BPM value used by Fixed mode and the first half of the tempo A/B.',
 'm-gate-add':'Append the chosen ideal gate on the chosen wire. CNOT uses that wire as control. Gates run after slider preparation.',
 'm-fx-compare':'Compare the same frozen take with the FX rack bypassed and processed. Level settings stay fixed; no loudness normalization.',
 'sample':'Simulate one fresh preparation and measurement, then audition the mapped note. It does not repeatedly collapse the same pair.',
 'new-take':'Advance the seed to create another 16-step sample from the same exact probabilities.',
 'cnot':'Apply CNOT with q0 as control and q1 as target. Depending on the input, it can create entanglement.',
 'compare':'A repeats this take in 12-TET; B uses Just or Custom tuning. Choose a non-equal tuning to enable it.',
 'save':'Save Music Lab settings in this browser/device. Export session JSON for a portable file.',
 'load':'Restore the Music Lab save from this browser. NMR has a separate save.',
 'export':'Download a Music Lab session: settings, state, probabilities, frequencies, seed and take. This is not an audio file.',
 'import':'Restore a Music Lab session JSON. NMR session JSON belongs in the NMR tab.',
 'music-loops':'Repeat the current 16-step take 1–16 times for audio export. Tempo and step size determine the sequence length.',
 'music-wav':'Render the current Music Lab take through the same synthesis graph used for live listening. Exports uncompressed stereo PCM16 audio.',
 'music-mp3':'Render this Music Lab take, then encode a stereo 128 kbps MP3. Encoder padding may extend decoded duration.',
 'map-major':'Assign major-chord intervals to the four outcomes. It changes the musical mapping, not the quantum state.',
 'map-minor':'Assign minor-chord intervals to the four outcomes. It changes the musical mapping, not the quantum state.',
 'basis0':'Choose the q0 measurement basis. Phase can affect X/Y outcomes even when Z populations stay unchanged.',
 'basis1':'Choose the q1 measurement basis. The probability bars show joint outcomes for both selected bases.',
 's-readout':'An optional ideal Ry(+90°) rotation maps Z toward transverse X before acquisition. None detects existing x/y coherence.',
 's-strike':'Replace preparation with a q0 Ry(+90°) demo and clear an imported matrix. This is not an extra gate added to the current input.',
 's-chord':'Replace preparation with Ry(+90°) on both spins; imported matrix preparation is cleared.',
 's-bell':'Replace preparation with an ideal Bell demo. Its local FID is zero for this observation; joint coherence can still exist.',
 's-clear':'Remove all circuit gates. Initial Bloch or imported-matrix preparation remains; Undo restores the previous configuration.',
 's-reset':'Restore NMR defaults, including preparation and musical settings. Undo can restore the prior NMR configuration.',
 's-undo':'Restore the previous NMR configuration, including imported matrices and gates.',
 's-echo-demo':'Load the Hahn echo lesson, setting J and offsets to zero to isolate the envelope. This changes NMR settings.',
 's-echo':'Apply ideal simultaneous spin refocusing during acquisition. This refocuses static spread, not irreversible T₂ decay or ZZ coupling.',
 's-compare-t2':'Compare homogeneous T₂ decay with additional Gaussian static-offset loss using otherwise shared settings.',
 's-compare-echo':'Compare FID and ideal spin echo with otherwise shared settings. Echo time is 2τ.',
 's-rho-import':'Inspect a full complex 4×4 effective matrix CSV/JSON. A table of fidelities cannot reconstruct a density matrix.',
 's-rho-clip':'Explicitly clip negative eigenvalues and renormalize the effective matrix. The original stays in the session; this is not a new measurement.',
 's-rho-use':'Use the inspected valid effective matrix, clearing gates, extra readout and echo. Simulation parameters remain unchanged.',
 's-calibrate':'Import user-provided T₁/T₂ values. Imported values are unverified and do not connect the app to hardware.',
 's-save':'Save the NMR configuration in this browser. It is separate from Music Lab saving.',
 's-restore':'Restore this browser’s NMR save. Music Lab has an independent save.',
 's-export':'Download the NMR configuration and any imported raw matrix/treatment as portable JSON.',
 's-import':'Restore NMR studio JSON. Music Lab has a different session format.',
 's-fid-json':'Download complex synthetic FID quadratures, time axis and NMR configuration for the documented Unity mapping.',
 's-fid-csv':'Download time, real and imaginary q0/q1 FID quadratures. This is numerical signal data, not audio.',
 's-fx':'Creative phase modulation and saturation in the sonification. It is separate from the physical relaxation model.',
 's-sound':'Choose how simulated observables become sound: FID carriers, conditional transitions, populations or excitation.',
 's-tauMs':'Refocusing delay τ in milliseconds. Ideal spin-echo refocusing occurs at 2τ.',
 's-j':'Weak scalar coupling J in hertz. It produces conditional transition splitting and beating in this model.',
 's-windowMs':'Physical acquisition window in milliseconds. Audio duration separately stretches this window into the exported sound.',
 's-column':'Add a logical circuit slot. A slot is not elapsed physical time; insert Wait for a delay.',
 's-dry':'Play the current NMR sonification without creative texture. Quantum evolution and relaxation are unchanged.',
 's-wet':'Play the current NMR sonification with creative phase modulation and saturation. This is an artistic audio mapping.',
 's-stereo':'Split routes q0 left and q1 right; centered mixes them into both channels. It does not imply spatially separated spins.'
};
for(let q=0;q<2;q++){help['theta'+q]='Initial polar angle before phase and optional CNOT. Watch the local Bloch vector and joint measurement probabilities.';help['phi'+q]='Initial relative quantum phase. X/Y readout can reveal phase changes that remain invisible in Z probabilities.';help['s-t1'+q]='Population relaxation time in milliseconds; this model requires T₂ ≤ 2T₁.';help['s-t2'+q]='Homogeneous transverse-coherence decay time. It is distinct from frequency and audio pitch.';help['s-star'+q]='Combined FID 1/e time including Gaussian static offsets; T₂* must not exceed T₂.';}
const tip=document.createElement('div');tip.setAttribute('popover','manual');tip.id='ui-tooltip';tip.className='ui-tooltip';tip.role='tooltip';tip.hidden=true;document.body.append(tip);
for(const [id,text] of Object.entries(help))if($(id))$(id).dataset.help=text;
function hideTip(){try{tip.hidePopover?.();}catch{}clearTimeout(tipTimer);clearTimeout(hideTimer);tip.hidden=true;if(tipOwner){const described=(tipOwner.getAttribute('aria-describedby')||'').split(' ').filter(x=>x&&x!=='ui-tooltip');if(described.length)tipOwner.setAttribute('aria-describedby',described.join(' '));else tipOwner.removeAttribute('aria-describedby');}tipOwner=null;}
function showTip(el){hideTip();if(!el?.dataset.help)return;tipOwner=el;el.removeAttribute('title');tip.textContent=el.dataset.help;tip.hidden=false;try{tip.showPopover?.();}catch{}const described=el.getAttribute('aria-describedby');el.setAttribute('aria-describedby',described?described+' ui-tooltip':'ui-tooltip');const r=el.getBoundingClientRect(),w=Math.min(340,window.innerWidth-24);tip.style.width=w+'px';tip.style.left=Math.max(12,Math.min(window.innerWidth-w-12,r.left))+'px';tip.style.top=Math.max(12,Math.min(window.innerHeight-tip.offsetHeight-12,r.bottom+9))+'px';}
document.addEventListener('pointerover',e=>{if(tip.contains(e.target)){clearTimeout(hideTimer);return;}const el=e.target.closest('[data-help]');if(el){clearTimeout(hideTimer);clearTimeout(tipTimer);tipTimer=setTimeout(()=>showTip(el),450);}});
document.addEventListener('pointerout',e=>{if(e.target.closest('[data-help]')||tip.contains(e.target)){clearTimeout(tipTimer);hideTimer=setTimeout(()=>{if(document.activeElement!==tipOwner)hideTip();},160);}});
document.addEventListener('focusin',e=>{const el=e.target.closest('[data-help]');if(el){clearTimeout(hideTimer);clearTimeout(tipTimer);tipTimer=setTimeout(()=>{if(document.activeElement===el)showTip(el);},160);}else if(!tip.contains(e.target))hideTip();});
document.addEventListener('focusout',()=>{hideTimer=setTimeout(()=>{if(document.activeElement!==tipOwner)hideTip();},160);});
document.addEventListener('keydown',e=>{if(e.key==='Escape')hideTip();});window.addEventListener('scroll',()=>{if(tipOwner){const el=tipOwner;if(document.activeElement===el)showTip(el);else hideTip();}},{passive:true});
for(const id of ['sample','new-take','compare','save','load','s-readout','s-rho-clip']){
  const target=$(id);if(!target)continue;const info=document.createElement('button');info.type='button';info.className='help-toggle';info.textContent='i';info.setAttribute('aria-label','Explain '+(target.textContent.trim()||id));info.dataset.help=help[id];info.addEventListener('click',()=>showTip(info));target.after(info);
}
// Tour is informational: no example loading, setting changes or autoplay.
const tour=document.createElement('dialog');tour.id='first-visit-tour';tour.className='tour-dialog spotlight-tour';tour.setAttribute('aria-labelledby','tour-title');tour.innerHTML='<div class="tour-shade shade-top"></div><div class="tour-shade shade-bottom"></div><div class="tour-shade shade-left"></div><div class="tour-shade shade-right"></div><div id="tour-spotlight" aria-hidden="true"></div><form id="tour-card" method="dialog"><button type="button" id="tour-skip" class="text-button tour-close">Skip tour</button><p id="tour-step" class="eyebrow"></p><h2 id="tour-title"></h2><p id="tour-text"></p><p id="tour-location" class="tour-location"></p><div class="tour-actions"><button type="button" id="tour-back" class="secondary-button">Back</button><button type="button" id="tour-next" class="play-button">Next</button></div></form>';document.body.append(tour);
const musicSteps=[
 ['Listen first','Press Play to hear the seeded melody. The state is simulated and the synthesizer is classical.','music','#play','1 · Listen'],
 ['Change one parameter','Move θ0 and compare probabilities and note occurrence rates. Phase may require X/Y readout.','music','#theta0','2 · Change one parameter'],
 ['Keep your sound','WAV/MP3 exports the current circuit. Audio options selects loops, Clean/Processed and tail. Saved auditions have their own Export this preview.','music','#music-quick-downloads','3 · Export']
];
const nmrSteps=[
 ['Listen to the simulated FID','Press Play FID. Changing a physical parameter creates a new simulation; Apply & audition listens to it.','studio','#s-play','1 · Listen'],
 ['Change coherence time','Change T₂* and listen again. Explore decay freezes rhythm for controlled comparison. Creative Model-linked BPM remains at 120–180.','studio','#s-star0','2 · Change one parameter'],
 ['Keep a version','WAV/MP3 uses current NMR settings. Frozen Preview only versions can be exported separately with a companion explanation TXT.','studio','#studio-quick-downloads','3 · Export']
];
let steps=musicSteps,tourBench='music';
let tourTarget=null,tourFrame=0,tourScroll=0;
function layoutTour(){if(!tour.hasAttribute('open')||!tourTarget)return;const vw=window.innerWidth,vh=window.innerHeight,r=tourTarget.getBoundingClientRect(),pad=8,left=Math.max(8,r.left-pad),right=Math.min(vw-8,r.right+pad),top=Math.max(8,r.top-pad),bottom=Math.min(vh-8,r.bottom+pad),spot=$('tour-spotlight');Object.assign(spot.style,{left:left+'px',top:top+'px',width:Math.max(24,right-left)+'px',height:Math.max(24,bottom-top)+'px'});const rects={top:[0,0,vw,top],bottom:[0,bottom,vw,vh-bottom],left:[0,top,left,bottom-top],right:[right,top,vw-right,bottom-top]};for(const [side,[x,y,w,h]] of Object.entries(rects))Object.assign(tour.querySelector('.shade-'+side).style,{left:x+'px',top:y+'px',width:Math.max(0,w)+'px',height:Math.max(0,h)+'px'});const card=$('tour-card'),width=Math.min(390,vw-24);card.style.width=width+'px';const height=card.getBoundingClientRect().height;let y=bottom+14;if(y+height>vh-12)y=top-height-14;if(y<12)y=Math.max(12,vh-height-12);const x=Math.max(12,Math.min(vw-width-12,left));Object.assign(card.style,{left:x+'px',top:y+'px'});}
function renderTour(){document.querySelectorAll('.tour-target').forEach(x=>x.classList.remove('tour-target'));const s=steps[tourAt];activate(s[2]);const target=document.getElementById('lab-transport')?({'#play':'#shared-play','#s-play':'#shared-play','#music-quick-downloads':'#shared-wav','#studio-quick-downloads':'#shared-wav'}[s[3]]||s[3]):s[3];tourTarget=document.querySelector(target);if(tourTarget){for(let p=tourTarget.parentElement;p;p=p.parentElement)if(p.tagName==='DETAILS')p.open=true;tourTarget.scrollIntoView?.({behavior:'instant',block:'center',inline:'nearest'});tourTarget.classList.add('tour-target');if(window.innerWidth<700&&!/jsdom/i.test(window.navigator.userAgent))window.scrollBy({top:window.innerHeight*.15,behavior:'instant'});}$('tour-step').textContent=`FIRST VISIT · ${tourAt+1} / ${steps.length}`;$('tour-title').textContent=s[0];$('tour-text').textContent=s[1];$('tour-location').textContent=s[4];$('tour-back').disabled=tourAt===0;$('tour-next').textContent=tourAt===steps.length-1?'Start exploring':'Next';layoutTour();window.cancelAnimationFrame(tourFrame);tourFrame=window.requestAnimationFrame(layoutTour);}
function openTour(bench='music'){tourBench=bench;steps=bench==='studio'?nmrSteps:musicSteps;tourReturn=active;tourFocus=document.activeElement;tourScroll=window.scrollY;tourAt=0;if(typeof tour.showModal==='function')tour.showModal();else tour.setAttribute('open','');renderTour();$('tour-next').focus({preventScroll:true});layoutTour();}
function closeTour(){document.querySelectorAll('.tour-target').forEach(x=>x.classList.remove('tour-target'));try{localStorage.setItem(tourBench==='studio'?'pundora-nmr-guide-seen-v1':SEEN,'seen');}catch{}if(typeof tour.close==='function')tour.close();else tour.removeAttribute('open');activate(tourReturn);tourFocus?.focus?.({preventScroll:true});if(typeof window.scrollTo==='function'&&!/jsdom/i.test(window.navigator.userAgent))window.scrollTo({top:tourScroll,behavior:'instant'});}
$('tour-back').addEventListener('click',()=>{tourAt=Math.max(0,tourAt-1);renderTour();});$('tour-next').addEventListener('click',()=>{if(tourAt===steps.length-1)closeTour();else{tourAt++;renderTour();}});$('tour-skip').addEventListener('click',closeTour);tour.addEventListener('cancel',e=>{e.preventDefault();closeTour();});$('guide-replay').addEventListener('click',()=>openTour());document.fonts?.ready.then(layoutTour);window.addEventListener('resize',layoutTour);window.addEventListener('scroll',layoutTour,{passive:true});
window.quantumUI={activate,openTour,closeTour,refreshTour:renderTour,get active(){return active;},get tourSteps(){return steps.length;}};
document.addEventListener('lab:activated',e=>{if(e.detail!=='studio'||tour.open)return;let seen=false;try{seen=localStorage.getItem('pundora-nmr-guide-seen-v1')==='seen';}catch{}if(!seen)queueMicrotask(()=>{if(active==='studio'&&!tour.open)openTour('studio');});});
activate('music');let seen=false;try{seen=localStorage.getItem(SEEN)==='seen';}catch{}if(!seen)openTour();
